function cookCancellable(dish, ms, signal) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => resolve(dish), ms);
    signal.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(new Error(`${dish} cancelled: ${signal.reason}`));
    });
  });
}

const controller = new AbortController();
const pie = cookCancellable("pie", 50, controller.signal);
setTimeout(() => controller.abort("customer left"), 10);

try {
  console.log(await pie);
} catch (err) {
  console.log(err.message);
}

