// The chapter's pretend kitchen. cook(dish, ms) starts a dish and returns
// a pager that buzzes with the dish after ms milliseconds.
// It prints a line when the dish starts and when it is done.
export function cook(dish, ms) {
  console.log(`  start ${dish}`);
  return new Promise((resolve) => {
    setTimeout(() => {
      console.log(`  done  ${dish} (${ms} ms)`);
      resolve(dish);
    }, ms);
  });
}

